const fetch = require('node-fetch');
const fs = require('fs');

async function mintNFT() {
  const url = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
  const apiKey = process.env.CROSSMINT_API_KEY || '';

  const payload = {
    recipient: 'email:test@example.com:polygon-amoy',
    metadata: {
      name: 'Welcome NFT',
      description: 'A welcome gift',
      image: 'https://example.com/nft.png'
    }
  };

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    });

    let data;
    try {
      data = await response.json();
    } catch (e) {
      data = await response.text();
    }

    if (!response.ok) {
      fs.writeFileSync('/home/user/mint_response.json', JSON.stringify({ error: `HTTP ${response.status}`, details: data }, null, 2));
    } else {
      fs.writeFileSync('/home/user/mint_response.json', JSON.stringify(data, null, 2));
    }
  } catch (error) {
    fs.writeFileSync('/home/user/mint_response.json', JSON.stringify({ error: error.message }, null, 2));
  }
}

mintNFT();

